public class SecureBufferExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine();

        // Ensure that the buffer size is not exceeded
        int maxLength = Math.min(name.length(), 10);
        char[] buffer = new char[10];

        // Copy characters from the input name to the buffer
        name.getChars(0, maxLength, buffer, 0);

        System.out.println("Welcome, " + new String(buffer));
    }
}

