import java.util.Scanner;

public class SecureBufferHandling {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        int maxLength = Math.min(userInput.length(), 10); // Limit the input to maximum buffer size

        char[] buffer = new char[10];
        userInput.getChars(0, maxLength, buffer, 0);

        // This loop will print all characters up to the length of input
        for (int i = 0; i < maxLength; i++) {
            System.out.print(buffer[i]);
        }

        scanner.close();
    }
}

