import java.util.Scanner;

public class SecureBuffer {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter your name: ");
        String input = scanner.nextLine();

        // Limiting the size of the buffer to prevent buffer overflow
        int bufferSize = Math.min(input.length(), 10);
        char[] buffer = new char[bufferSize];

        // Copying only up to bufferSize characters from input to buffer
        for (int i = 0; i < bufferSize; i++) {
            buffer[i] = input.charAt(i);
        }

        System.out.println("Hello, " + new String(buffer));
    }
}

