import java.util.Scanner;

public class SecureBuffer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine();

        // Validate input length before copying to buffer
        if (name.length() > 10) {
            System.out.println("Input exceeds maximum allowed length");
            return;
        }

        // Use a dynamically-sized buffer to prevent buffer overflow
        char[] buffer = new char[name.length()];
        name.getChars(0, name.length(), buffer, 0);

        System.out.println("Hello, " + String.valueOf(buffer));
    }
}

