public class SecureBufferHandling {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        // Dynamically allocate memory for the buffer based on user input length
        char[] buffer = new char[userInput.length()];

        // Perform bounds checking before copying user input into the buffer
        if (buffer.length <= 10) {
            userInput.getChars(0, userInput.length(), buffer, 0);
