public class SecureBufferHandling {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine();

        // Limit the input size to prevent buffer overflow
        int maxLength = 10;
        if (name.length() > maxLength) {
            System.out.println("Input exceeds maximum length of " + maxLength + ". Please try again.");
            return;
        }

        // Safe copy with proper bounds checking
        char[] buffer = new char[maxLength];
        name.getChars(0, Math.min(name.length(), maxLength), buffer, 0);

        System.out.println("Hello, " + String.valueOf(buffer));
    }
}

