public class SecureBufferUsage {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        // Limiting the buffer size to prevent buffer overflow
        char[] buffer = new char[Math.min(userInput.length(), 10)];

        userInput.getChars(0, Math.min(userInput.length(), 10), buffer, 0);

        // Ensuring that the loop does not access out-of-bounds index
        for (int i = 0; i < buffer.length; i++) {
            System.out.print(buffer[i]);
        }

        scanner.close();
    }
}

