import java.util.Scanner;

public class SecureBufferExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter your name: ");
        String name = scanner.nextLine();

        // Define a maximum buffer size to prevent buffer overflow
        int maxBufferSize = 10;

        char[] buffer = new char[maxBufferSize]; // Buffer with fixed size

        // Copy user input into buffer with bounds checking
        int length = Math.min(name.length(), maxBufferSize); // Ensure we don't exceed buffer size
        for (int i = 0; i < length; i++) {
            buffer[i] = name.charAt(i);
        }

        System.out.println("Hello, " + new String(buffer, 0, length)); // Printing the contents of the buffer
    }
}

