                    logger.logp(Level.FINE, CLASS_NAME, methodName, "set MappingMatch to: " + MappingMatch.EXACT);
                }
                servletPath = strippedUri;
                pathInfo = (jsessionIndex == -1) ? null : uri.substring(jsessionIndex);
            }

            //PK39337 - start
            if (node != root) {
