        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        // Set a maximum buffer size to prevent buffer overflow
        int bufferSize = 10;
        char[] buffer = new char[bufferSize];

        // Ensure that userInput does not exceed the buffer size
        int length = Math.min(userInput.length(), bufferSize);

        // Copy userInput into the buffer array safely
        for (int i = 0; i < length; i++) {
            buffer[i] = userInput.charAt(i);
        }

