import java.io.*;

public class XSSFixedCode {
    public static void main(String[] args) {
        // Simulating user input from a form field
        String userInput = "<script>alert('XSS Vulnerability!')</script>";

        // Sanitize user input by escaping HTML special characters
        String sanitizedInput = escapeHtml(userInput);

        // Output the sanitized result to the console
        String output = "Welcome, " + sanitizedInput;
        System.out.println(output);
    }

    private static String escapeHtml(String input) {
        return input.replaceAll("&", "&amp;")
                    .replaceAll("<", "&lt;")
                    .replaceAll(">", "&gt;")
                    .replaceAll("\"", "&quot;")
                    .replaceAll("'", "&#39;");
    }
}

