import java.util.Scanner;

public class SafeBufferHandling {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine(); // Use nextLine() to read entire line

        // Ensure that input does not exceed buffer size
        byte[] buffer = new byte[10];
        int length = Math.min(name.length(), buffer.length);
        System.arraycopy(name.getBytes(), 0, buffer, 0, length);

        System.out.println("Hello, " + new String(buffer, 0, length));
    }
}

