        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        int maxLength = 10;
        char[] buffer = new char[maxLength];

        // Ensure input length does not exceed buffer size
        if (input.length() > maxLength) {
            System.out.println("Input exceeds maximum allowed length. Truncating...");
            input = input.substring(0, maxLength);
        }

        input.getChars(0, input.length(), buffer, 0);

        System.out.println("Buffer contents: " + new String(buffer));
