public class BufferOverflowFixed {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        // Ensure that the buffer size does not exceed the input length
        int bufferSize = Math.min(input.length(), 10); // Set buffer size to maximum of 10

        char[] buffer = new char[bufferSize];

        // Copy the user input into the buffer with proper bounds checking
        for (int i = 0; i < bufferSize; i++) {
